/* Brief product sheets based on the supplied FICHAS TECNCAS documents.
   No doses, efficacy percentages or certifications are inferred. */
const TECHNICAL_SHEETS={
 'antigrasa':{source:'FICHA TECNICA - ARCHER Antigrasa.doc',action:'Desengrasante líquido con tensoactivos que ayudan a desprender la grasa adherida.',surfaces:'Cocinas, extractores, mesones, azulejos y superficies lavables al agua.',use:'Aplicar, dejar actuar y retirar con esponja. Enjuagar o pasar un paño húmedo.',care:'Utilizar guantes de goma.'},
 'vajillero':{source:'FICHA TECNICA - ARCHER Detergente Vajillero.doc',action:'Detergente líquido espumante que remueve grasa y residuos de alimentos.',surfaces:'Platos, ollas, vasos, vajilla y cristalería.',use:'Aplicar una pequeña cantidad sobre una esponja húmeda, lavar cada pieza y enjuagar con agua.',care:'Dejar escurrir después del enjuague.'},
 'limpia-vidrios':{source:'FICHA TECNICA - ARCHER Limpia Vidrios.doc',action:'Limpiador con tensoactivos y componentes de secado rápido que ayudan a evitar huellas y aureolas.',surfaces:'Ventanas, vitrinas, espejos y otras superficies lavables indicadas en la etiqueta.',use:'Rociar y frotar con un paño o toalla de papel hasta dejar la superficie limpia.',care:'Consultar la compatibilidad de la superficie antes de aplicar.'},
 'limpia-banos':{source:'FICHA TECNICA - ARCHER Limpia Baños.docx',action:'Limpiador con tensoactivos y agente biocida para limpiar, desinfectar y aromatizar.',surfaces:'Sanitarios, lavamanos, tinas, azulejos y superficies duras del baño.',use:'Rociar, dejar actuar unos minutos, pasar una esponja y enjuagar con agua.',care:'Utilizar guantes de goma.'},
 'quitasarro':{source:'FICHA TECNICA - ARCHER Quitasarro.doc',action:'Desincrustante de reacción ácida para remover sarro y depósitos adheridos.',surfaces:'Inodoros, lavamanos, tinas y juntas de cerámica indicadas en la etiqueta.',use:'Aplicar sobre la zona a tratar, dejar actuar unos minutos y enjuagar con abundante agua.',care:'Utilizar guantes y evitar el contacto con piel y ojos. No mezclar con lavandina.'},
 'quitasarro-extra':{source:'FICHA TECNICA - ARCHER Quitasarro.doc',action:'Desincrustante de reacción ácida para tratar sarro e incrustaciones.',surfaces:'Sanitarios y superficies compatibles indicadas en la etiqueta.',use:'Aplicar sobre la zona a tratar, dejar actuar unos minutos y enjuagar con abundante agua.',care:'Utilizar guantes y evitar el contacto con piel y ojos. No mezclar con lavandina.'},
 'desinfectante-pisos':{source:'FICHA TECNICA - ARCHER Desinfectante de Pisos..._.doc / FICHA TECNICA - ARCHER Desinfectante de Pisos.doc',action:'Limpiador con agente desinfectante que ayuda a remover suciedad y grasa, dejando un aroma agradable.',surfaces:'Pisos, paredes, mesones, azulejos y superficies lavables.',use:'Aplicar con un paño siguiendo las instrucciones de la etiqueta de la presentación elegida.',care:'Consultar al equipo técnico la dilución y el tiempo de contacto para cada aplicación.'},
 'lustra-muebles':{source:'FICHA TECNICA - ARCHER Lustra Muebles.docx',action:'Fórmula con abrillantadores y agentes protectores que forma una película de brillo seco.',surfaces:'Muebles de madera.',use:'Limpiar la superficie, aplicar el producto y pasar un paño limpio y seco hasta obtener brillo.',care:'Usar sobre el material indicado en la etiqueta.'},
 'cera-autobrillo':{source:'FICHA TECNICA - ARCHER Cera al agua.doc',action:'Cera de base acuosa que forma una película protectora y brillante sin necesidad de lustrar.',surfaces:'Pisos lavables de cerámica, granito, vinilo y mosaico.',use:'Limpiar el piso, extender uniformemente con un paño y dejar secar durante 30 minutos.',care:'No usar sobre pisos de madera. Elegir la variedad adecuada al color del piso.'},
 'germasep':{source:'FICHA TECNICA - ARCHER Germasep con Amonio Cuaternario..doc',action:'Desinfectante formulado con amonio cuaternario de quinta generación y tensoactivo no iónico.',surfaces:'Pisos, paredes, azulejos, sanitarios y otras superficies lavables.',use:'Limpiar previamente la suciedad. Aplicar el producto según la etiqueta; en superficies sensibles a la humedad, utilizar un paño.',care:'No mezclar con otros productos ni utilizar para desinfectar alimentos. Evitar contacto con piel y ojos.'},
 'lavandina':{source:'FICHA TECNICA - ARCHER Lavandina.doc / FICHA TECNICA - ARCHER Super Lavandina.doc / FICHA TECNICA - ARCHER Desinfectante Blanqueador.doc',action:'Soluciones de hipoclorito de sodio con acción oxidante, desinfectante y blanqueadora.',surfaces:'Pisos, azulejos y ropa compatible con blanqueadores clorados, según la variedad.',use:'Seleccionar la variedad y respetar la dilución indicada en su etiqueta: las concentraciones no son iguales.',care:'No mezclar con otros productos. Evitar contacto con ojos y piel. Mantener fuera del alcance de niños.'},
 'detergente-ropa':{source:'FICHA TECNICA - ARCHER Detergente de Ropa Lavado a Máquina.doc',action:'Detergente líquido con tensoactivos y complejos enzimáticos para remover suciedad con espuma controlada.',surfaces:'Prendas aptas para lavado a máquina.',use:'Pretratar las manchas y dosificar en la lavadora según la carga y el grado de suciedad.',care:'Seguir las instrucciones de lavado de cada prenda y la dosificación del envase.'},
 'suavizante':{source:'FICHA TECNICA - ARCHER Suavizante.docx',action:'Agentes suavizantes que acondicionan las fibras, reducen la estática y facilitan el planchado.',surfaces:'Prendas textiles compatibles con suavizante.',use:'Agregar en el compartimiento de suavizantes durante el último ciclo de enjuague, según la carga.',care:'Respetar la dosificación de la etiqueta. Las variedades aromáticas incorporan fragancia.'},
 'classic-sanitizador':{source:'FICHA TECNICA - CLASSIC Sanitizador.doc',action:'Sanitizador en gel para la higiene de manos, de aplicación sin enjuague.',surfaces:'Manos.',use:'Aplicar en la palma y friccionar ambas manos, extendiendo el producto hasta que se desvanezca.',care:'Mantener alejado de fuentes de fuego.'},
 'classic-alcohol':{source:'FICHA TECNICA -CLASSIC Alcohol Antibacterial.doc',action:'Alcohol antibacterial con glicerina, un humectante que ayuda a evitar la sequedad de las manos.',surfaces:'Manos. Uso externo.',use:'Aplicar, extender y dejar secar al aire. No requiere enjuague ni toalla.',care:'Conservar por debajo de 25 °C, bien cerrado y lejos de llamas o chispas.'},
 'supremo-shampoo':{source:'FICHA TECNICA - SUPREMO Shampoo.doc',action:'Shampoo con agentes limpiadores para la higiene y el cuidado del cabello.',surfaces:'Cabello.',use:'Aplicar sobre el cabello mojado, masajear suavemente y enjuagar.',care:'Elegir la variedad adecuada y seguir las instrucciones del envase.'},
 'supremo-jabon':{source:'FICHA TECNICA - SUPREMO Jabón Líquido.doc',action:'Jabón líquido con agente antibacterial para la limpieza de manos y cuerpo.',surfaces:'Manos y piel del cuerpo.',use:'Aplicar sobre las manos húmedas, frotar durante 30 segundos y enjuagar.',care:'Secar después del enjuague. Seguir las indicaciones del envase.'}
};
const TECHNICAL_GROUPS={cocina:['antigrasa','vajillero'],superficies:['limpia-vidrios','limpia-banos','quitasarro','quitasarro-extra','desinfectante-pisos','lustra-muebles','cera-autobrillo','germasep','lavandina'],lavanderia:['detergente-ropa','suavizante'],higiene:['classic-sanitizador','classic-alcohol','supremo-shampoo','supremo-jabon']};
const technicalNormalize=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function technicalCard(p){const t=TECHNICAL_SHEETS[p.id],v=p.variants.find(v=>v.liters===5);return `<article class="sheet-card" data-sheet="${p.id}" data-search="${esc(technicalNormalize(p.name+' '+p.brand+' '+t.action+' '+t.surfaces))}"><div class="sheet-art"><span>5 L</span><img loading="lazy" src="${v.image}" alt="${esc(p.name)} en presentación de 5 litros"></div><div class="sheet-copy"><span class="eyebrow">${esc(p.brand)}</span><h3>${esc(p.name)}</h3><p>${esc(t.action)}</p><button class="technical-link" data-technical="${p.id}">Abrir ficha técnica <span aria-hidden="true">↗</span><span class="sr-only"> de ${esc(p.name)}</span></button></div></article>`}
institutional=function(){const products=C.filter(p=>p.institutional&&TECHNICAL_SHEETS[p.id]&&p.variants.some(v=>v.liters===5));return `<section class="institutional-cover"><div class="shell institutional-cover-grid"><div><span class="eyebrow">MULTI INTERNACIONAL · LÍNEA INSTITUCIONAL</span><h1>La confianza empieza<br>por conocer<br><em>cada producto.</em></h1><p>Soluciones de limpieza para empresas, instituciones y distribuidores. Conoce sus aplicaciones y cuidados en fichas técnicas claras y fáciles de consultar.</p><a class="button white" href="#biblioteca-tecnica" data-scroll-request>Explorar fichas técnicas ↓</a><a class="institutional-contact" href="#institucional-solicitud" data-scroll-request>Hablar con el equipo comercial ↗</a></div><div class="institutional-cover-art"><img src="${rasset('2 Un Cuidado para todo/Institucional.png')}" alt="Línea de limpieza institucional"><div><span>INFORMACIÓN PARA ELEGIR MEJOR</span><strong>El producto adecuado.<br>La aplicación correcta.</strong></div></div></div></section><section class="institutional-benefits shell" aria-label="Información disponible"><div><span>01</span><p><strong>Presentaciones de 5 litros</strong>Identifica el producto para tu operación.</p></div><div><span>02</span><p><strong>Uso y cuidados</strong>Consulta dónde y cómo aplicarlo.</p></div><div><span>03</span><p><strong>Atención para empresas</strong>Solicita documentación y asesoramiento.</p></div></section><section class="shell section technical-library" id="biblioteca-tecnica"><div class="section-heading"><div><span class="eyebrow">BIBLIOTECA DE PRODUCTOS</span><h2>Fichas técnicas.</h2><p>Elige un producto para conocer qué hace, dónde se usa y cómo aplicarlo.</p></div><span class="library-label">CONSULTA DIRECTA · SIN REGISTRO</span></div><div class="technical-tools"><label for="sheet-search">Busca un producto o superficie<input id="sheet-search" type="search" placeholder="Ej.: antigrasa, pisos, manos…" autocomplete="off"></label><div class="sheet-filters" aria-label="Filtrar fichas por aplicación">${[['todos','Todos'],['cocina','Cocina'],['superficies','Pisos y superficies'],['lavanderia','Lavandería'],['higiene','Higiene personal']].map(([id,label])=>`<button data-sheet-filter="${id}" aria-pressed="${id==='todos'}">${label}</button>`).join('')}</div></div><p id="sheet-count" role="status">${products.length} fichas disponibles</p><div class="technical-grid">${products.map(technicalCard).join('')}</div><p id="sheet-empty" hidden>No encontramos una ficha con ese nombre. Prueba otra palabra o consulta a nuestro equipo.</p><div class="institutional-documentation"><div><span class="eyebrow">RESPALDO PARA TU OPERACIÓN</span><h3>¿Necesitas documentación para tu empresa?</h3><p>Estas fichas resumen la documentación técnica de Multi Internacional. Para procesos de compra, distribución o mercados internacionales, solicita la documentación específica del producto y la presentación que necesitas.</p></div><a class="button navy" href="#institucional-solicitud" data-scroll-request>Solicitar información ↗</a></div></section>${businessForm('institucional-solicitud','Conversemos sobre tu operación.','Institucional')}`};
function filterTechnicalSheets(){const search=technicalNormalize(document.getElementById('sheet-search').value),group=document.querySelector('[data-sheet-filter][aria-pressed="true"]').dataset.sheetFilter;let count=0;document.querySelectorAll('[data-sheet]').forEach(card=>{card.hidden=!(card.dataset.search.includes(search)&&(group==='todos'||TECHNICAL_GROUPS[group].includes(card.dataset.sheet)));if(!card.hidden)count++});document.getElementById('sheet-count').textContent=`${count} ${count===1?'ficha disponible':'fichas disponibles'}`;document.getElementById('sheet-empty').hidden=count!==0;}
document.addEventListener('input',event=>{if(event.target.id==='sheet-search')filterTechnicalSheets()});
document.addEventListener('click',event=>{const filter=event.target.closest('[data-sheet-filter]');if(filter){document.querySelectorAll('[data-sheet-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===filter)));filterTechnicalSheets()}});
function openTechnical(id){
 const p=C.find(p=>p.id===id),t=TECHNICAL_SHEETS[id];if(!p||!t)return;
 const v=p.variants.find(v=>v.liters===5);if(!v)return;
 productDialog.dataset.brand=p.brand.toLowerCase();
 productDialog.innerHTML=`<button class="dialog-close icon-button" data-close aria-label="Cerrar ficha técnica">×</button><div class="product-detail technical-detail"><div class="detail-art"><img src="${v.image}" alt="${esc(p.brand+' '+p.name+' '+v.label)}"><p>${esc(v.label)} · Imagen de referencia de esta presentación</p></div><div class="detail-content"><span class="eyebrow">FICHA TÉCNICA RESUMIDA · ${esc(p.brand)}</span><h2 id="product-title">${esc(p.name)}</h2><p class="technical-action">${esc(t.action)}</p><dl><dt>Dónde se usa</dt><dd>${esc(t.surfaces)}</dd><dt>Cómo se aplica</dt><dd>${esc(t.use)}</dd><dt>Cuidados de uso</dt><dd>${esc(t.care)}</dd></dl><p class="micro">Resumen basado en la documentación técnica de Multi Internacional. Sigue siempre la etiqueta de la presentación elegida.</p><a class="button navy" href="${wa('Hola, solicito información técnica y comercial de '+p.brand+' '+p.name+' en formato de 5 litros para mi empresa.')}" target="_blank" rel="noopener">Consultar este producto ↗</a></div></div>`;
 if(!productDialog.open)productDialog.showModal();
}
document.addEventListener('click',event=>{const b=event.target.closest('[data-technical]');if(b)openTechnical(b.dataset.technical)});
route();
